import Image from "next/image";

/**
 * 3D icon set (Microsoft Fluent Emoji 3D, MIT licence). Files live in public/icons/3d,
 * generated by `npm run icons` from scripts/fetch-3d-icons.mjs.
 */
export const iconNames = [
  "award", "chart", "bot", "boxes", "brain", "briefcase", "building", "cloud", "code", "compass",
  "cpu", "database", "factory", "film", "gauge", "globe", "education", "handshake", "health", "bank",
  "layers", "leaf", "idea", "lock", "monitor", "palette", "plane", "puzzle", "refresh", "rocket",
  "server", "shield", "cart", "mobile", "sparkles", "store", "target", "truck", "users", "workflow",
  "wrench", "zap", "mail", "phone", "pin", "clock", "check", "growth", "money", "key", "cloudbolt",
] as const;

export type IconName = (typeof iconNames)[number];

/** Deterministic negative delay so floating icons drift out of sync */
const floatDelay = (name: string) => `-${[...name].reduce((a, c) => a + c.charCodeAt(0), 0) % 6}s`;

export function Icon({
  name,
  className = "size-10",
  float = true,
}: {
  name: IconName;
  /** Size utilities (e.g. size-10). Colour utilities have no effect on 3D icons. */
  className?: string;
  /** Gentle idle float. Turn off for small inline icons (menus, chips, footers). */
  float?: boolean;
}) {
  return (
    <Image
      src={`/icons/3d/${name}.webp`}
      alt=""
      aria-hidden="true"
      width={96}
      height={96}
      unoptimized
      draggable={false}
      className={`icon3d ${float ? "icon3d-float" : ""} shrink-0 select-none ${className}`}
      style={float ? ({ "--float-delay": floatDelay(name) } as React.CSSProperties) : undefined}
    />
  );
}
